export const CreateItemResponseSchema = z.looseObject({
  item: ItemDetailSchema,
  created: z.boolean(),
});
export type CreateItemResponse = z.infer<typeof CreateItemResponseSchema>;

export const GetItemResponseSchema = z.looseObject({
  item: ItemDetailSchema,
  children: z.array(ItemSummarySchema),
  links: z.array(LinkSchema),
  comments: z.array(CommentSchema),
  comments_next_cursor: z.string().nullable(),
  history: z.array(HistoryEventSchema).optional(),
  development: DevelopmentSchema.optional(),
});
export type GetItemResponse = z.infer<typeof GetItemResponseSchema>;

export const ItemWriteResponseSchema = z.looseObject({ item: ItemDetailSchema });
export type ItemWriteResponse = z.infer<typeof ItemWriteResponseSchema>;

export const SearchItemsResponseSchema = z.looseObject({
  items: z.array(ItemSearchResultSchema),
  next_cursor: z.string().nullable(),
});
export type SearchItemsResponse = z.infer<typeof SearchItemsResponseSchema>;
